43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
57	const CURSE_SURCHARGE_PERCENT = 50;
58	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
59	const HIGH_ENCHANTMENT_THRESHOLD = 5;
60	const LOYALTY_DISCOUNT_PERCENT = 20;
61	const LOYALTY_THRESHOLD_YEARS = 2;
62	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
63	
64	/**
65	 * Everything the pricing rules need to know about an item type lives here, so
66	 * that "what is a rune?" has a single answer. Components are the small parts
67	 * (runes, moonstones) that can be bought as a building block; main items
68	 * (swords, amulets, ...) never form a block.
69	 */
70	const ITEM_TYPES: Record<string, { unitPremium: number; isComponent: boolean }> =
71	  {
72	    sword: { unitPremium: 100, isComponent: false },
73	    amulet: { unitPremium: 60, isComponent: false },
74	    staff: { unitPremium: 80, isComponent: false },
75	    potion: { unitPremium: 40, isComponent: false },
76	    rune: { unitPremium: 25, isComponent: true },
77	    moonstone: { unitPremium: 25, isComponent: true },
78	  };
79	
80	/** A building block of 3 alike components is offered at this base premium. */
81	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
82	const COMPONENT_BLOCK_SIZE = 3;
83	
84	/** Tallies how many items of each type a policy covers, e.g. [["rune", 3]]. */
85	const countByType = (items: Item[]): [string, number][] => {
86	  const counts = new Map<string, number>();
87	  for (const item of items) {
88	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
89	  }
90	  return [...counts];
91	};
92	
93	/**
94	 * Prices every item of one type together, because exactly 3 alike components
95	 * form a block charged as one. "Alike" means the same type, and the block does
96	 * not repeat: 4 or 7 runes are each priced per item.
97	 */
98	const basePremiumForType = (type: string, count: number): number => {
99	  const { unitPremium, isComponent } = ITEM_TYPES[type];
100	  return isComponent && count === COMPONENT_BLOCK_SIZE
101	    ? COMPONENT_BLOCK_BASE_PREMIUM
102	    : count * unitPremium;
103	};
104	
105	const sumOfBasePremiums = (items: Item[]): number =>
106	  countByType(items).reduce(
107	    (sum, [type, count]) => sum + basePremiumForType(type, count),
108	    0,
109	  );
110	
111	/**
112	 * Item-specific modifiers: each applies to one item and is charged as a
113	 * percentage of THAT item's unit premium, never of the policy total.
114	 * They stack — an item matching several rules is charged for each.
115	 *
116	 * Unit premium, not the item's share of the policy base: the two differ only
117	 * for components inside a block of 3 (billed 60 G for three 25 G runes), and
118	 * no test pins down a surcharged component yet. Revisit when one does.
119	 */
120	const ITEM_MODIFIERS: { appliesTo: (item: Item) => boolean; rate: number }[] = [
121	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_PERCENT },
122	  {
123	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
124	    rate: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
125	  },
126	];
127	
128	const surchargeForItem = (item: Item): number =>
129	  ITEM_MODIFIERS.filter(({ appliesTo }) => appliesTo(item)).reduce(
130	    (sum, { rate }) => sum + percent(ITEM_TYPES[item.type].unitPremium, rate),
131	    0,
132	  );
133	
134	const sumOfItemSurcharges = (items: Item[]): number =>
135	  items.reduce((sum, item) => sum + surchargeForItem(item), 0);
136	
137	/**
138	 * Policy-wide modifiers: each is charged as a percentage of the POLICY BASE
139	 * premium (the sum of item base premiums, before any item surcharge), so no
140	 * modifier is ever computed on top of another. Discounts carry a negative rate.
141	 */
142	interface PolicyContext {
143	  customer: Customer;
144	  /** Quotes already issued to this customer earlier in the scenario. */
145	  previousContracts: number;
146	}
147	
148	const POLICY_MODIFIERS: {
149	  appliesTo: (context: PolicyContext) => boolean;
150	  rate: number;
151	}[] = [
152	  // Always applies: every item in a quote is treated as a first insurance,
153	  // regardless of how long the customer has been with the MHPCO.
154	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_PERCENT },
155	  {
156	    // Negative rate: a discount is just a surcharge pointing the other way, so
157	    // it needs no separate code path and cannot stack onto another modifier.
158	    appliesTo: ({ customer }) =>
159	      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
160	    rate: -LOYALTY_DISCOUNT_PERCENT,
161	  },
162	  {
163	    appliesTo: ({ previousContracts }) => previousContracts >= 1,
164	    rate: -FOLLOW_UP_DISCOUNT_PERCENT,
165	  },
166	];
167	
168	const sumOfPolicyAdjustments = (
169	  context: PolicyContext,
170	  policyBasePremium: number,
171	): number =>
172	  POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(context)).reduce(
173	    (sum, { rate }) => sum + percent(policyBasePremium, rate),
174	    0,
175	  );
176	
177	const premiumFor = (context: PolicyContext, items: Item[]): number => {
178	  const policyBasePremium = sumOfBasePremiums(items);
179	  return Math.ceil(
180	    policyBasePremium +
181	      sumOfItemSurcharges(items) +
182	      sumOfPolicyAdjustments(context, policyBasePremium) +
183	      PROCESSING_FEE,
184	  );
185	};
186	
187	export const runScenario = (scenario: Scenario): ScenarioResult => {
188	  let previousContracts = 0;
189	  const results = scenario.steps.map((step) => {
190	    const quote = step as QuoteStep;
191	    const premium = premiumFor(
192	      { customer: scenario.customer, previousContracts },
193	      quote.items,
194	    );
195	    previousContracts += 1;
196	    return { premium };
197	  });
198	  return { results };
199	};
