/**
 * Steps are executed in order because a step's result can depend on the ones
 * before it: only the count of contracts already issued carries across steps so
 * far, but claims will later have to share a remaining cap the same way.
 */
export const runScenario = (scenario: Scenario): ScenarioResult => {
  let previousContracts = 0;
  const results = scenario.steps.map((step): StepResult => {
    if (step.op === "claim") {
      throw new Error("Claims are not supported yet");
    }
    const premium = premiumFor(
      { customer: scenario.customer, previousContracts },
      step.items,
    );
    // Counted after pricing, so a quote never discounts itself, and only for
    // quotes, because a claim does not issue a contract.
    previousContracts += 1;
    return { premium };
  });
  return { results };
};
